n25351.content:
\begin{definition}[Forgetting a coordinate]
  \label{def:forget}
  \uses{}
  \lean{NOF.forget}
  \leanok

  For an index $i : [d]$, we define
  \begin{align}
    \forget_i : G^d & \to G^{\{j : [d] \mid j \ne i\}} \\
    x & \mapsto j \mapsto x_j
  \end{align}
\end{definition}

n25352.content:
\begin{definition}[Forbidden pattern]
  \label{def:forbidden-pattern}
  \uses{}
  \lean{NOF.IsForbiddenPatternWithTip, NOF.IsForbiddenPattern}
  \leanok

  We say a tuple $(a_1, \dots, a_d) : (G^d)^d$ is a {\bf forbidden pattern with tip $v : G^d$} if
  $$a_{i, j} = v_j$$
  for all $i, j$ distinct. We also simply say $(a_1, \dots, a_d)$ is a {\bf forbidden pattern} if it is a forbidden pattern with tip $v$ for some $v$.
\end{definition}

n25353.content:
\begin{definition}[Multidimensional corner]
  \label{def:multicorner}
  \uses{def:forbidden-pattern}
  \lean{NOF.IsMultidimCorner}
  \leanok

  A {\bf multidimensional corner} in $d$ dimensions is a tuple of the form $(x, x + ce_1, \dots, x + ce_d)$ for some $x : G^d$ and $c : G$, where $ce_i$ is the vector of all zeroes except in position $i$ where it is $c$. Such a corner is said to be {\bf trivial} if $c = 0$.
\end{definition}

n25354.content:
\begin{definition}[Corner-free number]
  \label{def:corner-free-num}
  \uses{def:multicorner}
  % \lean{}
  % \leanok

  The {\bf $d$-dimensional corner-free} number of $G$, denoted $r_d(G)$ is the size of the largest set $A$ in $G^d$ such that $A$ doesn't contain a non-trivial corner.
\end{definition}

n25355.content:
\begin{definition}[Corner-coloring number]
  \label{def:corner-color-num}
  \uses{def:multicorner}
  % \lean{}
  % \leanok

  The {\bf $d$-dimensional corner-coloring number} of $G$, denoted $\chi_d(G)$, is the smallest number of colors one needs to color $G^d$ such that no non-trivial $d$-dimensional corner is monochromatic.
\end{definition}

n25356.content:
\begin{lemma}[Lower bound on the corner-coloring number]
  \label{lem:corner-num-lower}
  \uses{def:corner-free-num, def:corner-color-num}
  % \lean{}
  % \leanok

  $$r_d(G) \chi_d(G) \ge N^d$$
\end{lemma}

n25357.content:
\begin{proof}
  % \uses{}
  % \leanok

  Find a coloring of $G^d$ in $\chi_d(G)$ colors without non-trivial monochromatic $d$-dimensional corners. The coloring partitions $G^d$ into $\chi_d(G)$ sets of size at most $r_d(G)$.
\end{proof}

n25358.content:
\begin{lemma}[Upper bound on the corner-coloring number]
  \label{lem:corner-num-upper}
  \uses{def:corner-free-num, def:corner-color-num}
  % \lean{}
  % \leanok

  $$r_d(G) \chi_d(G) \le 2d N^d \log N$$
\end{lemma}

n25359.content:
\begin{proof}
  % \uses{}
  % \leanok

  Find $A$ a corner-free set of density $\alpha = r_d(G)/N^d$. If we pick $m > d\log N/\alpha$ translates of $A$ randomly, then the expected number of elements not covered by any translate is
  $$N^d(1 - \alpha)^m \le \exp(dN - m\alpha) < 1$$
  Namely, there is some collection of $m$ translates of $A$ that covers all of $G^d$. Since being corner-free is translation-invariant, this cover by translates gives a coloring in $m$ colors without non-trivial monochromatic corners. So
  $$\chi_d(G) \le m \le 2d \log N/\alpha = 2d N^d \log N/r_d(G)$$
  if we set eg $m = \left\lfloor d\log N/\alpha\right\rfloor + 1$.
\end{proof}

n25360.content:
\begin{definition}[NOF protocol]
  \label{def:protocol}
  \lean{NOF.Protocol}
  \leanok

  A {\bf NOF protocol} $P$ consists of maps
  \begin{align}
    \strat : & [d] \to G^{d - 1} \to \leanList \Bool \to \Bool \\
    \guess : & [d] \to G^{d - 1} \to \leanList \Bool \to \Bool
  \end{align}
\end{definition}

n25361.content:
\begin{definition}[NOF broadcast]
  \label{def:broadcast}
  \uses{def:protocol, def:forget}
  \lean{NOF.Protocol.broadcast}
  \leanok

  Given a NOF protocol $P$, the {\bf NOF broadcast on input $x : G^d$} is inductively defined by
  \begin{align}
    \broad(x) : \mathbb{N}& \to \leanList \Bool \\
    0 & \mapsto [] \\
    t + 1 & \mapsto \strat_{t \% d}(\forget_{t \% d}(x), \broad(x, t)) :: \broad(x, t)
  \end{align}
\end{definition}

n25362.content:
\begin{lemma}[Length of a broadcast]
  \label{lem:length-broadcast}
  \uses{def:broadcast}
  \lean{NOF.Protocol.length_broadcast}
  \leanok
  For every NOF protocol $P$, every input $x : G^d$ and every time $t$, $\broad(x, t)$ has length $t$.
\end{lemma}

n25364.content:
\begin{definition}[Valid NOF protocol]
  \label{def:valid-protocol}
  \uses{def:broadcast}
  \lean{NOF.Protocol.IsValid}
  \leanok

  Given a function $F : G^d \to \Bool$, the NOF protocol $P$ is {\bf valid in $F$ at time $t$ on input $x$} if all participants correctly guess $F(x)$, namely if
  $$\guess_i(\forget_i(x), \broad(x, t)) = F(x)$$
  for all $i : [d]$.
\end{definition}

n25365.content:
\begin{definition}[The trivial protocol]
  \label{def:trivial-protocol}
  \uses{def:protocol}
  \lean{NOF.Protocol.trivial}
  % \leanok

  For all $F$, we define the {\bf trivial protocol} by making participant $i$ do "Send the $t / d$-th bit of the number of participant $i + 1$" and "Compute $x_i$ from the binary representation given by participant $i - 1$, then compute $F(x)$".
\end{definition}

n25366.content:
\begin{lemma}[The trivial protocol is valid]
  \label{lem:trivial-protocol-valid}
  \uses{def:valid-protocol, def:trivial-protocol}
  % \lean{}
  % \leanok

  For all $F$, the trivial protocol for $F$ is valid in time $d\left\lceil \log_2 n\right\rceil$.
\end{lemma}

n25368.content:
\begin{definition}[Deterministic complexity of a protocol]
  \label{def:det-protocol-complex}
  \uses{def:valid-protocol}
  \lean{NOF.Protocol.complexity}
  \leanok

  The {\bf communication complexity of a NOF protocol $P$ for $F$} is the smallest time $t$ such that $P$ is valid in $F$ at time $t$ on all inputs $x$, or $\infty$ if no such $t$ exists.
\end{definition}

n25369.content:
\begin{definition}[Deterministic complexity of a function]
  \label{def:det-fun-complex}
  \uses{def:det-protocol-complex}
  \lean{NOF.funComplexity}
  \leanok

  The {\bf deterministic communication complexity of a function} $F$, denoted $D(F)$, is the minimum of the communication complexity of $P$ when $P$ ranges over all NOF protocols.
\end{definition}

n25370.content:
\begin{lemma}[Trivial bound on the function complexity]
  \label{lem:trivial-bound-det-fun-complex}
  \uses{def:det-fun-complex}
  % \lean{}
  % \leanok

  The communication complexity of any function $F$ is at most $d\left\lceil \log_2 n\right\rceil$.
\end{lemma}

n25371.content:
\begin{proof}
  \uses{lem:trivial-protocol-valid}
  % \leanok

  The trivial protocol is a protocol valid in $F$ in time $d\left\lceil \log_2 n\right\rceil$.
\end{proof}

n25372.content:
\begin{lemma}[The tip of a monochromatic forbidden pattern]
  \label{lem:mono-forbidden-pattern-tip}
  \uses{def:forbidden-pattern, def:valid-protocol}
  \lean{NOF.IsForbiddenPatternWithTip.broadcast_eq}
  \leanok

  Given $P$ a NOF protocol and a time $t$, if $(a_1, \dots, a_d)$ is a forbidden pattern with tip $v$ such that $\broad(a_i, t)$ equals some fixed broadcast history $b$ for all $i$, then $\broad(v, t) = b$ as well.
\end{lemma}

n25374.content:
\begin{definition}[$\eval$ function]
  \label{def:eval}
  \lean{NOF.eval}
  \leanok

  The {\bf $\eval$ function} is defined by
  \begin{align}
      \eval : G^d & \to \Bool \\
      x & \mapsto \begin{cases}
      1 & \text{ if } \sum_i x_i = 0 \\
      0 & \text{ else}
    \end{cases}
  \end{align}
\end{definition}

n25375.content:
\begin{lemma}[Forbidden patterns project to multidimensional corners]
  \label{lem:forbidden-pattern-project-multicorner}
  \uses{def:forbidden-pattern, def:multicorner, def:forget, def:eval}
  \lean{NOF.isMultidimCorner_forget_of_isForbiddenPattern}
  \leanok

  If $(a_1, \dots, a_d)$ is a forbidden pattern such that $\eval(a_i) = 1$ for all $i$, then
  $$(\forget_i(a_1), \dots, \forget_i(a_d))$$
  is a multidimensional corner for all index $i$.
\end{lemma}

n25376.content:
\begin{proof}
  \uses{}
  \leanok
  Let $v$ be the tip of $(a_1, \dots, a_d)$. Then, using that $\sum_k a_{j, k} = 0$ and $v_k = a_{j, k}$ for all $k \ne j$, we see that $v_j = a_{j, j} + \sum_k v_k$. This means that $(\forget_i(a_1), \dots, \forget_i(a_d)$ is a multidimensional corner by setting $x = \forget_i(a_i)$ and $c = \sum_k v_k$.
\end{proof}

n25377.content:
\begin{lemma}[Monochromatic forbidden patterns are trivial]
  \label{lem:mono-forbidden-pattern-trivial}
  \uses{def:forbidden-pattern, def:valid-protocol, def:eval}
  \lean{NOF.trivial_of_isForbiddenPattern_of_isValid_eval}
  \leanok

  Given $P$ a NOF protocol valid in time $t$ for $\eval$, all monochromatic forbidden patterns are trivial.
\end{lemma}

n25378.content:
\begin{proof}
  \uses{lem:length-broadcast, lem:mono-forbidden-pattern-tip}
  \leanok

  Assume $(a_1, \dots, a_d)$ is a monochromatic forbidden pattern with tip $v$, say $\broad(a_i, t) = b$ for all $i$. By Lemma \ref{lem:mono-forbidden-pattern-tip}, we also have $\broad(v, t) = b$. Since $P$ is a valid NOF protocol for $\eval$, we get $\eval(a_i) = \eval(v)$ for all $i$, meaning that $(a_1, \dots, a_d) = (v, \dots, v)$ is trivial.
\end{proof}

n25379.content:
\begin{theorem}[Lower bound for $D(\eval)$ in terms of $\chi_d(G)$]
  \label{thm:det-fun-complex-eval-ge-corner-color-num}
  \uses{def:det-fun-complex, def:eval, def:corner-color-num}
  % \lean{}
  % \leanok

  $$D(\eval) \ge \lceil\log_2\chi_d(G)\rceil$$
\end{theorem}

n25381.content:
\begin{corollary}[Lower bound for $D(\eval)$ in terms of $r_d(G)$]
  \label{cor:det-fun-complex-eval-ge-corner-free-num}
  \uses{def:det-fun-complex, def:eval, def:corner-free-num}
  % \lean{}
  % \leanok

  $$D(\eval) \ge d\log_2\frac N{r_d(G)}$$
\end{corollary}

n25382.content:
\begin{proof}
  \uses{thm:det-fun-complex-eval-ge-corner-color-num, lem:corner-num-lower}
  % \leanok

  Putting Theorem \ref{thm:det-fun-complex-eval-ge-corner-color-num} and Lemma \ref{lem:corner-num-lower} together, we get
  $$D(\eval) \ge \left\lceil \log_2\frac{2dN^d\log N}{r_d(G)}\right\rceil \ge d\log_2\frac N{r_d(G)}$$
\end{proof}

n25384.content:
\begin{lemma}[The non-monochromatic protocol is valid]
  \label{lem:non-monochromatic-protocol-valid}
  \uses{def:non-monochromatic-protocol, def:valid-protocol}
  % \lean{}
  % \leanok

  If $c$ is a coloring such that all monochromatic forbidden patterns are trivial, then the non-monochromatic protocol for $c$ is valid in time $\lceil\log_2\chi_d(G)\rceil + d$.
\end{lemma}

n25385.content:
\begin{proof}
  \uses{}
  % \leanok

  We have
  $$\text{answer is } 1 \iff \text{ all $a_i$ have the same color } \iff \text{ all $a_i$ are equal } \iff \sum_i x_i = 0$$
  where the first equivalence holds by definition, the second one holds by assumption and the third one holds since the $a_i$ form a forbidden pattern.
\end{proof}

n25386.content:
\begin{theorem}[Upper bound for $D(\eval)$ in terms of $\chi_d(G)$]
  \label{thm:det-fun-complex-eval-le-corner-color-num}
  \uses{def:det-fun-complex, def:eval, def:corner-color-num}
  % \lean{}
  % \leanok

  $$D(\eval) \le \lceil\log_2\chi_d(G)\rceil + d$$
\end{theorem}

n25387.content:
\begin{proof}
  \uses{lem:non-monochromatic-protocol-valid, lem:forbidden-pattern-project-multicorner}
  % \leanok

  Using Lemma \ref{lem:forbidden-pattern-project-multicorner}, find some coloring $c$ of $\{x \mid \sum_i x_i = 0\}$ in $\chi_d(G)$ colors such that all monochromatic forbidden patterns are trivial. Then Lemma \ref{lem:non-monochromatic-protocol-valid} tells us that the non-monochromatic protocol for $c$ is valid in time $\lceil\log_2\chi_d(G)\rceil + d$.
\end{proof}

n25388.content:
\begin{corollary}[Upper bound for $D(\eval)$ in terms of $r_d(G)$]
  \label{cor:det-fun-complex-eval-le-corner-free-num}
  \uses{def:det-fun-complex, def:eval, def:corner-free-num}
  % \lean{}
  % \leanok

  $$D(\eval) \le 2d\log_2\frac N{r_d(G)}$$ % Feel free to replace the 2d by any other constant
\end{corollary}

n25389.content:
\begin{proof}
  \uses{thm:det-fun-complex-eval-le-corner-color-num, lem:corner-num-upper}
  % \leanok

  Putting Theorem \ref{thm:det-fun-complex-eval-le-corner-color-num} and Lemma \ref{lem:corner-num-upper} together, we get
  $$D(\eval) \le \left\lceil \log_2\frac{2dN^d\log N}{r_d(G)}\right\rceil \le 2d\log_2\frac N{r_d(G)}$$
\end{proof}

n25390.content:
\begin{definition}[Randomised complexity of a protocol]
  \label{def:rand-protocol-complex}
  \uses{def:valid-protocol}
  % \lean{}
  % \leanok

  The {\bf communication complexity of a randomised NOF protocol $P$ for $F$ with error $\epsilon$} is the smallest time $t$ such that
  $$\mathbb P(x \mid P \text{ is not valid at time } t) \le \epsilon$$
  or $\infty$ if no such $t$ exists.
\end{definition}

n25391.content:
\begin{definition}[Randomised complexity of a function]
  \label{def:rand-complex}
  \uses{def:rand-protocol-complex}
  % \lean{}
  % \leanok

  The {\bf randomised communication complexity of a function $F$ with error $\epsilon$}, denoted $R_\epsilon(F)$, is the minimum of the randomised communication complexity of $P$ when $P$ ranges over all randomised NOF protocols.
\end{definition}

n25392.content:
\begin{definition}[The randomised equality testing protocol for $\eval$]
  \label{def:rand-eq-test-protocol-eval}
  \uses{def:protocol}
  % \lean{}
  % \leanok

  The {\bf randomised equality testing protocol for $\eval$}

n25393.content:
\begin{lemma}[The randomised equality testing protocol for $\eval$ is valid]
  \label{lem:rand-eq-test-protocol-eval-valid}
  \uses{def:rand-eq-test-protocol-eval, def:valid-protocol}
  % \lean{}
  % \leanok

  The randomised equality testing protocol is valid for $\eval$ at time $2d$.
\end{lemma}

n25394.content:
\begin{proof}
  % \uses{}
  % \leanok

  If $\eval(x) = 1$, then the protocol guesses correctly. Else it errors with probability
  $$2^{-\lceil{\log_2\epsilon^{-1}}\rceil} \le \epsilon$$
\end{proof}

n25395.content:
\begin{theorem}[The randomised complexity of $\eval$ is constant]
  \label{thm:eval-rand-complexity}
  \uses{def:eval, def:rand-complex}
  % \lean{}
  % \leanok

  $$R_\epsilon(\eval) \le 2d\lceil\log_2\epsilon^{-1}\rceil$$
\end{theorem}

n25396.content:
\begin{proof}
  \uses{lem:rand-eq-test-protocol-eval-valid}
  % \leanok

  By Lemma \ref{lem:rand-eq-test-protocol-eval-valid}, the randomised equality testing protocol is valid for $\eval$ at time $2d$.
\end{proof}
